tinymce.PluginManager.add("productlink", function (editor) {
    editor.ui.registry.addAutocompleter("productlink", {
        trigger: "@",
        minChars: 1,

        fetch: function (pattern) {
            return fetch(`/search?keyword=${encodeURIComponent(pattern)}`)
                .then((res) => res.json())
                .then((data) => {
                    return data.map((product) => ({
                        value: JSON.stringify(product),
                        text: product.NameProduct,
                    }));
                });
        },

        onAction: function (autocompleteApi, rng, value) {
            const product = JSON.parse(value);

            const html = `
                <span class="product-tag" data-id="${product.IdProduct}">
                    ${product.NameProduct}
                </span>
            `;

            editor.selection.setRng(rng);
            editor.insertContent(html);

            autocompleteApi.hide();
        },
    });

    editor.ui.registry.addButton("productlink", {
        text: "Link Product",
        onAction: function () {
            let node = editor.selection.getNode();

            if (node && !node.classList?.contains("product-tag")) {
                node = editor.dom.getParent(node, ".product-tag");
            }

            if (!node) {
                alert("Hãy đặt con trỏ vào tên sản phẩm!");
                return;
            }

            const productId = node.getAttribute("data-id");

            fetch(`/product/${productId}`)
                .then((res) => res.json())
                .then((product) => {
                    if (!product) {
                        alert("Không tìm thấy sản phẩm");
                        return;
                    }

                    const imageUrl = product.ImageURL;

                    const html = `
                        <div>
                            <a href="/products/${product.IdProduct}" target="_blank" style="text-decoration:none;color:black;">
                                <img src="${imageUrl}" style="width:75%;height:auto;margin-bottom:5px;">
                                <div style="font-weight:bold;">${product.NameProduct}</div>
                            </a>
                        </div>
                    `;

                    editor.selection.select(node);
                    editor.selection.setContent(html);

                    editor.selection.collapse(false);
                    editor.insertContent("&nbsp;");
                })
                .catch((err) => console.error(err));
        },
    });
});
